import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function ProfilePage() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Password Update State
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [message, setMessage] = useState(null);
  const [error, setError] = useState(null);
  const [isUpdating, setIsUpdating] = useState(false);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const res = await API.get('/auth/profile');
      setProfile(res.data);
      setLoading(false);
    } catch (err) {
      console.error("Error fetching profile:", err);
      setLoading(false);
    }
  };

  const handleUpdatePassword = async (e) => {
    e.preventDefault();
    setMessage(null);
    setError(null);

    if (newPassword !== confirmPassword) {
      setError("New passwords do not match");
      return;
    }

    setIsUpdating(true);
    try {
      const res = await API.put('/auth/update-password', {
        currentPassword,
        newPassword
      });
      setMessage(res.data.message || "Password updated successfully");
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
    } catch (err) {
      setError(err.response?.data?.message || "Failed to update password");
    } finally {
      setIsUpdating(false);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="relative pt-20 bg-surface min-h-screen">
        <div className="flex flex-col w-full max-w-4xl mx-auto p-6 space-y-8">

          <header className="mb-6">
            <h1 className="font-display-lg text-display-lg text-on-surface">
              Account Profile
            </h1>
            <p className="font-body-md text-on-surface-variant opacity-80 mt-1">
              Manage your personal data and security settings
            </p>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-12 gap-8">

            {/* User Data Section */}
            <div className="md:col-span-5 flex flex-col gap-6">
              <div className="bg-surface-container/60 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 shadow-lg">
                <div className="flex items-center gap-4 mb-8">
                  <div className="w-16 h-16 rounded-2xl bg-electric-blue/20 text-electric-blue border border-electric-blue/30 flex items-center justify-center text-2xl font-bold">
                    {profile?.name ? profile.name.charAt(0).toUpperCase() : 'U'}
                  </div>
                  <div>
                    <h2 className="text-xl font-title-lg text-on-surface">{profile?.name || 'Unknown User'}</h2>
                    <span className="px-2 py-0.5 mt-1 inline-block bg-primary/10 text-primary border border-primary/20 rounded font-data-mono text-xs">
                      ADMINISTRATOR
                    </span>
                  </div>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-1 tracking-widest">EMAIL ADDRESS</label>
                    <div className="font-body-md text-on-surface bg-surface-dim px-4 py-3 rounded-xl border border-glass-stroke">
                      {profile?.email || 'N/A'}
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-1 tracking-widest">MOBILE NUMBER</label>
                    <div className="font-body-md text-on-surface bg-surface-dim px-4 py-3 rounded-xl border border-glass-stroke">
                      {profile?.mobileNumber || 'Not provided'}
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-1 tracking-widest">MEMBER SINCE</label>
                    <div className="font-data-mono text-on-surface bg-surface-dim px-4 py-3 rounded-xl border border-glass-stroke">
                      {profile?.createdAt ? new Date(profile.createdAt).toLocaleDateString() : 'N/A'}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Password Update Section */}
            <div className="md:col-span-7">
              <div className="bg-surface-container/40 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 shadow-lg h-full">
                <h3 className="font-headline-md text-on-surface mb-6 flex items-center gap-2">
                  <span className="material-symbols-outlined text-vibrant-violet">lock</span>
                  Security Settings
                </h3>

                {message && (
                  <div className="mb-6 p-4 rounded-xl bg-primary/10 border border-primary/30 text-primary flex items-center gap-3">
                    <span className="material-symbols-outlined">check_circle</span>
                    {message}
                  </div>
                )}

                {error && (
                  <div className="mb-6 p-4 rounded-xl bg-error-red/10 border border-error-red/30 text-error-red flex items-center gap-3">
                    <span className="material-symbols-outlined">error</span>
                    {error}
                  </div>
                )}

                <form onSubmit={handleUpdatePassword} className="flex flex-col gap-5">
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">CURRENT PASSWORD</label>
                    <input 
                      type="password" 
                      required 
                      value={currentPassword} 
                      onChange={(e) => setCurrentPassword(e.target.value)} 
                      className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">NEW PASSWORD</label>
                    <input 
                      type="password" 
                      required 
                      value={newPassword} 
                      onChange={(e) => setNewPassword(e.target.value)} 
                      className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-label-caps text-on-surface-variant mb-2 tracking-widest">CONFIRM NEW PASSWORD</label>
                    <input 
                      type="password" 
                      required 
                      value={confirmPassword} 
                      onChange={(e) => setConfirmPassword(e.target.value)} 
                      className="w-full bg-surface-container-highest border border-glass-stroke rounded-xl p-3.5 text-on-surface focus:border-vibrant-violet focus:ring-1 focus:ring-vibrant-violet outline-none transition-all" 
                    />
                  </div>

                  <div className="mt-4 border-t border-glass-stroke pt-6 flex justify-end">
                    <button 
                      type="submit" 
                      disabled={isUpdating}
                      className="px-8 py-3.5 rounded-full bg-vibrant-violet text-background font-label-caps tracking-widest hover:bg-opacity-90 transition-all shadow-[0_0_20px_rgba(139,92,246,0.4)] disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {isUpdating ? (
                        <>
                          <span className="material-symbols-outlined animate-spin text-[18px]">sync</span>
                          UPDATING...
                        </>
                      ) : (
                        <>
                          UPDATE PASSWORD
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            </div>

          </div>
        </div>
      </main>
    </Layout>
  );
}

export default ProfilePage;
